sys_script_fix.script:
var gr = new GlideRecord("incident");
if (gr.get('f4e9975c976f6690a78db62de053af38')) {

    // Get the Base64 string from the description field.
    var base64String = gr.description;

    // Check if the field has a value.
    if (base64String) {

        // Correctly decode the Base64 string into a byte array.
        var base64Bytes = GlideStringUtil.base64DecodeAsBytes(base64String);

        // Use the GlideSysAttachment API to create the attachment.
        var attachment = new GlideSysAttachment();

        // Define the filename and let ServiceNow infer the content type.
        var fileName = "image.png";

        // The .write() method is the key. It correctly creates the attachment record
        // and stores the binary data in the sys_attachment_doc table.
        // It requires 4 arguments: tableName, tableSysId, fileName, and the binary data.
        var attachmentSysId = attachment.write(gr.getTableName(), gr.getUniqueValue(), fileName, base64Bytes);

        gs.info("Attachment created with sys_id: " + attachmentSysId);
    }
}
